#: Features the seeded VIP role grants.
VIP_FEATURES = "beta_features,places,search"


def seed_rows(apps, schema_editor):
    """The rows a new install starts with: the shared Demolished status, the VIP role, and the first-party OAuth client."""
    Label = apps.get_model("dashboard", "Label")
    Label.objects.get_or_create(
        profile=None,
        name="Demolished",
        kind="status",
        defaults={"icon": "\U0001f480", "color": "#795548", "order": 60, "is_protected": True},
    )
    SubscriptionRole = apps.get_model("dashboard", "SubscriptionRole")
    SubscriptionRole.objects.get_or_create(
        slug="vip",
        defaults={"name": "VIP", "description": "Grants access to VIP-only features.", "features": VIP_FEATURES, "storage_quota_gb": 500},
    )
    Application = apps.get_model("oauth2_provider", "Application")
    Application.objects.update_or_create(
        client_id=FIRST_PARTY_CLIENT_ID,
        defaults={
            "name": FIRST_PARTY_CLIENT_NAME,
            "client_type": "public",
            "authorization_grant_type": "authorization-code",
            "redirect_uris": " ".join(FIRST_PARTY_REDIRECT_URIS),
            # A public client has no secret. Unhashed, the empty string matches no secret a client could send; hashed,
            # it would be a valid hash of "".
            "client_secret": "",
            "hash_client_secret": False,
            "user": None,
            "skip_authorization": False,
        },
    )


#: Coordinates are immutable after insert, enforced by the database so no code path can drift a shared Location.
FREEZE_LOCATION_IDENTITY = """
CREATE OR REPLACE FUNCTION dashboard_locations_freeze_identity() RETURNS trigger AS $$
BEGIN
    IF NEW.latitude IS DISTINCT FROM OLD.latitude
       OR NEW.longitude IS DISTINCT FROM OLD.longitude
    THEN
        RAISE EXCEPTION 'dashboard_locations coordinates are immutable (id=%). '
            'Get-or-create a new Location for the changed coordinates instead of mutating this row.',
            OLD.id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER dashboard_locations_freeze_identity
    BEFORE UPDATE ON dashboard_locations
    FOR EACH ROW EXECUTE FUNCTION dashboard_locations_freeze_identity();
"""
UNFREEZE_LOCATION_IDENTITY = """
DROP TRIGGER IF EXISTS dashboard_locations_freeze_identity ON dashboard_locations;
DROP FUNCTION IF EXISTS dashboard_locations_freeze_identity();
"""


