        migrations.CreateModel(
            name="ApiCallLog",
            fields=[
                ("id", models.BigAutoField(auto_created=True, primary_key=True, serialize=False, verbose_name="ID")),
                ("created", models.DateTimeField(auto_now_add=True)),
                ("updated", models.DateTimeField(auto_now=True)),
                ("service", models.CharField(db_index=True, help_text="Service identifier matching ApiRateLimit.service.", max_length=50)),
                ("endpoint", models.TextField(blank=True, help_text="URL or endpoint path called.")),
                ("success", models.BooleanField(default=True, help_text="False if the call raised an exception or returned a non-2xx status.")),
                ("response_ms", models.IntegerField(blank=True, help_text="Round-trip response time in milliseconds.", null=True)),
                ("status_code", models.PositiveSmallIntegerField(blank=True, help_text="The upstream's HTTP status. Null when no response arrived (refused before sending, a network error) or the caller had none to record.", null=True)),
                ("was_rate_limited", models.BooleanField(default=False, help_text="True if this entry records a call that was blocked by rate limiting.")),
                ("was_geo_filtered", models.BooleanField(default=False, help_text="True if this entry records a call that was skipped due to geography filtering.")),
                ("was_service_disabled", models.BooleanField(default=False, help_text="True if this entry records a call that was skipped due to service being disabled.")),
                ("was_rejected_input", models.BooleanField(db_default=False, default=False, help_text="True if this entry records a call refused before it was made because its input could not return data (services.core.input_validation).")),
                (
                    "calls",
                    models.PositiveIntegerField(
                        db_default=1,
                        default=1,
                        help_text="How many calls this row stands for: 1, except for a service whose calls are tallied and rolled up once a minute (services.core.call_tally), where it is every call that minute with the same outcome. Its response_ms is their mean.",
                    ),
                ),
                (
                    "profile",
                    models.ForeignKey(
                        blank=True,
                        help_text="Whose behalf this call was made on, from the actor bound for the request. Null for the site's own scheduled work, which is nobody's consumption, and for a call whose account has since been deleted - the usage stays in the record, unattributed.",
                        null=True,
                        on_delete=django.db.models.deletion.SET_NULL,
                        related_name="api_calls",
                        to="dashboard.profile",
                    ),
                ),
            ],
            options={
                "verbose_name": "API Call Log",
                "verbose_name_plural": "API Call Logs",
                "db_table": "dashboard_api_call_log",
                "ordering": ["-created"],
                "abstract": False,
            },
        ),
